                <x-filament::icon :icon="\Filament\Support\Icons\Heroicon::OutlinedMagnifyingGlassPlus" class="h-4 w-4" />
            </span>
        @endif
    </div>

    {{-- Lightbox: teleport su body per uscire dallo stacking/overflow del slide-over.
