        ->modalFooterActionsAlignment(Alignment::Start)
        ->schema(function (Schema $schema, array $arguments): Schema {
            $media = $this->findOwnedMedia($arguments['media'] ?? null);

            return $schema->components($media === null ? [] : [
                Grid::make(['default' => 1, 'lg' => 2])->schema([
                    // colonna sinistra: anteprima (con "sostituisci file" sopra) + tab info/metadati
                    Group::make([
                        SchemaActions::make([
                            $this->replaceAssetFileAction()->button()->color('gray')->arguments(['media' => $media->getKey()]),
                        ])->alignEnd(),
                        ViewEntry::make('preview')
                            ->hiddenLabel()
                            ->view('digital-hub::filament.partials.asset-preview', [
                                'media' => $media,
                                // URL protetti da sessione: nel pannello l'utente è autenticato
                                'posterUrl' => AssetPreview::url($media),
                                'originalUrl' => AssetUrl::original($media),
                            ]),
                        $this->assetInfoTabs($media),
                    ]),
                    // colonna destra: nome editabile (etichetta `name` di Spatie Media,
                    // non il file fisico — salvataggio live al blur, niente submit del form)
                    Group::make([
                        TextInput::make('name')
                            ->label(__('digital-hub::assets.display_name'))
                            ->default($media->name)
                            ->required()
                            ->maxLength(255)
                            ->live(onBlur: true)
                            ->afterStateUpdated(function (?string $state) use ($media): void {
                                if (! is_string($state) || $state === '' || $state === $media->name) {
                                    return;
                                }

                                $media->name = $state;
                                $media->save();

                                Notification::make()->success()->title(__('digital-hub::assets.name_updated'))->send();
                            }),
                    ]),
                ]),
            ]);
        });
}

