// colonna sinistra: anteprima con "sostituisci file" in overlay sopra
// (sull'asse z, non sopra nel layout) + tab info/metadati.
// L'action resta un vero componente dello schema (`Actions`), non solo
// un `{{ $action }}` renderizzato dentro il blade della preview: mounta
// un'action mentre infoAsset è già mounted richiede che la nuova action
// sia risolvibile nell'albero dello schema corrente (come le action del
// footer, 14e) — altrimenti Livewire non riesce a risolverla e l'azione
// non parte. La sovrapposizione visiva è ottenuta via CSS (`extraAttributes`),
// non spostando l'action fuori dallo schema.
Group::make([
    Group::make([
        ViewEntry::make('preview')
            ->hiddenLabel()
            ->view('digital-hub::filament.partials.asset-preview', [
                'media' => $media,
                // URL protetti da sessione: nel pannello l'utente è autenticato
                'posterUrl' => AssetPreview::url($media),
                'originalUrl' => AssetUrl::original($media),
            ]),
        Actions::make([
            $this->replaceAssetFileAction()->button()->color('primary')->arguments(['media' => $media->getKey()]),
        ])->extraAttributes(['class' => 'absolute left-5 top-5 z-10']),
    ])->extraAttributes(['class' => 'relative']),
    $this->assetInfoTabs($media),
]),

