5	namespace AtrioTeam\DigitalHub\Assets\Support;
6	
7	/**
8	 * Stato di elaborazione di un asset (digital-hub #16/#18).
9	 *
10	 * Al caricamento un media entra `pending`; un job in coda
11	 * ({@see \AtrioTeam\DigitalHub\Assets\Jobs\ProcessAssetJob}) estrae metadati e
12	 * dimensioni (oggi) e potrà generare taglie/altre elaborazioni (domani),
13	 * portandolo a `completed` o, in caso di errore, a `failed`.
14	 *
15	 * pending vs processing è una distinzione interna (in coda vs in lavorazione):
16	 * all'utente sono presentati uguali ("In elaborazione"), vedi {@see self::label()}.
17	 *
18	 * Valore null sulla colonna `media.processing_status` = asset non gestito dalla
19	 * pipeline (media legacy o di altre collection): in UI è trattato come neutro.
20	 */
21	enum AssetProcessingStatus: string
22	{
23	    case Pending = 'pending';
24	    case Processing = 'processing';
25	    case Completed = 'completed';
26	    case Failed = 'failed';
27	
28	    /**
29	     * In lavorazione: in coda o in elaborazione. La UI mostra l'overlay di attesa.
30	     */
31	    public function isInProgress(): bool
32	    {
33	        return $this === self::Pending || $this === self::Processing;
34	    }
35	
36	    public function isFailed(): bool
37	    {
38	        return $this === self::Failed;
39	    }
40	
41	    /**
42	     * Etichetta localizzata per la UI (chiave `assets.status_<valore>`).
43	     */
44	    public function label(): string
45	    {
46	        return (string) __('digital-hub::assets.status_' . $this->value);
47	    }
48	}
