{{-- Anteprima asset in cima al pannello info: immagine se visualizzabile,
     player per audio, poster/icona per video e pdf. Variabile attesa: $media.

     Per immagini, video e PDF l'anteprima è cliccabile e apre uno zoom
     (lightbox) a tutto schermo: immagini e video "in grande", PDF in un viewer
     embedded. L'audio resta col solo player inline; gli altri tipi (archivi,
     documenti, cad, generici) non hanno zoom — vedi AssetFileType::isZoomable().

     Il bottone "Sostituisci file" (14d) NON vive qui: è un componente `Actions`
     dello schema del pannello info (AssetManager::infoAssetAction()), sovrapposto
     via CSS a un contenitore `relative` che avvolge questo partial. Perché è
     mountato mentre infoAsset è già aperto, dev'essere anche registrato come
     modal action del genitore via `->registerModalActions()` sull'action
     `infoAsset` — altrimenti Livewire non riesce a risolverlo (il semplice
     posizionamento nello schema non basta). --}}
@php
    $type = \AtrioTeam\DigitalHub\Assets\Support\AssetFileType::fromMedia($media);
    // URL di poster e originale forniti dal chiamante (partial agnostico sulla fonte):
    // il pannello info passa gli URL gati via sessione, la gallery di share (22g) passa
    // signed URL temporanei per l'accesso senza account.
    $poster = $posterUrl;
    $url = $originalUrl;
    $zoomable = $type->isZoomable();
@endphp
<div x-data="{ zoom: false }">
    {{-- Box anteprima: cliccabile (apre lo zoom) per i tipi ingrandibili. --}}
    <div
        @if ($zoomable)
            role="button"
            title="{{ __('digital-hub::assets.zoom') }}"
            x-on:click="zoom = true"
        @endif
        @class([
            'relative flex items-center justify-center rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50 p-3',
            'cursor-zoom-in group' => $zoomable,
        ])
        style="min-height: 9rem;"
    >
        @if ($type->isImage())
            <img src="{{ $url }}" alt="{{ $media->file_name }}" class="max-h-64 max-w-full rounded object-contain" loading="lazy" />
        @elseif ($type->isAudio())
            {{-- audio: solo player inline, niente zoom --}}
            <audio src="{{ $url }}" controls preload="metadata" class="w-full">
                {{ __('digital-hub::assets.player_unsupported') }}
            </audio>
        @elseif ($type->isVideo() || $poster)
            {{-- video / pdf: poster (frame o prima pagina) se disponibile, altrimenti
                 icona del tipo; il contenuto interattivo vive nello zoom --}}
            @if ($poster)
                <img src="{{ $poster }}" alt="{{ $media->file_name }}" class="max-h-64 max-w-full rounded object-contain" loading="lazy" />
            @else
                <x-filament::icon :icon="$type->icon()" class="h-20 w-20 text-gray-300 dark:text-gray-600" />
            @endif
            {{-- video: icona play in overlay sul poster --}}
            @if ($type->isVideo())
                <span class="pointer-events-none absolute inset-0 flex items-center justify-center">
                    <span class="flex h-12 w-12 items-center justify-center rounded-full bg-black/50 text-white shadow">
                        <x-filament::icon :icon="\Filament\Support\Icons\Heroicon::Play" class="h-7 w-7 ml-0.5" />
                    </span>
                </span>
            @endif
        @else
            <x-filament::icon :icon="$type->icon()" class="h-20 w-20 text-gray-300 dark:text-gray-600" />
        @endif

        {{--  "ingrandisci" all'hover sull'anteprima cliccabile --}}
        @if ($zoomable)
            <span class="pointer-events-none absolute right-2 top-2 flex h-7 w-7 items-center justify-center rounded-full bg-black/40 text-white opacity-0 transition-opacity group-hover:opacity-100">
                <x-filament::icon :icon="\Filament\Support\Icons\Heroicon::OutlinedMagnifyingGlassPlus" class="h-4 w-4" />
            </span>
        @endif
    </div>

    {{-- Lightbox: teleport su body per uscire dallo stacking/overflow del slide-over.
         Il contenuto è montato con x-if solo a zoom aperto, così video/PDF si caricano
         all'apertura e si smontano (fermandosi) alla chiusura. --}}
    @if ($zoomable)
        <template x-teleport="body">
            <div
                x-show="zoom"
                x-cloak
                x-transition.opacity
                x-on:keydown.escape.window="zoom = false"
                x-on:click.self="zoom = false"
                class="fixed inset-0 flex items-center justify-center bg-black/80 p-4"
                style="z-index: 9999;"
            >
                {{-- Chiudi --}}
                <button
                    type="button"
                    x-on:click="zoom = false"
                    title="{{ __('digital-hub::assets.zoom_close') }}"
                    class="absolute right-4 top-4 flex h-10 w-10 items-center justify-center rounded-full bg-white/10 text-white transition-colors hover:bg-white/20"
                >
                    <x-filament::icon :icon="\Filament\Support\Icons\Heroicon::OutlinedXMark" class="h-6 w-6" />
                </button>

                <template x-if="zoom">
                    @if ($type->isImage())
                        <img src="{{ $url }}" alt="{{ $media->file_name }}" class="max-h-[90vh] max-w-[95vw] rounded object-contain shadow-2xl" />
                    @elseif ($type->isVideo())
                        <video src="{{ $url }}" controls autoplay playsinline @if ($poster) poster="{{ $poster }}" @endif class="max-h-[90vh] max-w-[95vw] rounded shadow-2xl">
                            {{ __('digital-hub::assets.player_unsupported') }}
                        </video>
                    @else
                        {{-- pdf: viewer nativo del browser --}}
                        <iframe src="{{ $url }}" title="{{ $media->file_name }}" class="h-[90vh] w-[90vw] rounded bg-white shadow-2xl"></iframe>
                    @endif
                </template>
            </div>
        </template>
    @endif
</div>

