17	use Tests\TestCase;
18	
19	/**
20	 * Preview delle tile cartella nell'AssetManager (14b): collage fino a 4
21	 * miniature dai media contenuti nella sottocartella o nei suoi discendenti,
22	 * saltando i media senza nulla di mostrabile; polling esteso ai sottoalberi
