25	class AssetFolderPreviewTest extends TestCase
26	{
27	    use RefreshDatabase;
28	
29	    private Product $product;
30	
31	    protected function setUp(): void
32	    {
33	        parent::setUp();
34	
35	        Storage::fake('assets');
36	        $this->actingAs(User::factory()->create());
37	        Filament::setCurrentPanel('admin');
38	
39	        $this->product = Product::create(['name' => ['it' => 'Tavolo']]);
40	    }
41	
42	    public function test_subfolder_preview_uses_image_from_descendant_folder(): void
43	    {
44	        $parent = $this->product->createAssetFolder('Documenti');
45	        $child = $this->product->createAssetFolder('2024', $parent);
46	        $grandchild = $this->product->createAssetFolder('Gennaio', $child);
47	
48	        // l'immagine sta due livelli sotto la tile: deve contare comunque
49	        $this->addImage($grandchild);
50	
51	        $previews = $this->pageWithActiveFolder($parent)->getSubfolderPreviews();
52	
53	        $this->assertCount(1, $previews[$child->id]);
54	        $this->assertStringContainsString('/assets/', $previews[$child->id][0]);
55	    }
56	
57	    public function test_media_without_displayable_preview_is_skipped(): void
58	    {
59	        $parent = $this->product->createAssetFolder('Documenti');
60	        $child = $this->product->createAssetFolder('Audio', $parent);
61	
62	        // niente poster generato e non è un'immagine → nessuna miniatura, tile a icona
63	        $this->product
64	            ->addMediaFromString('not an image')
65	            ->usingFileName('track.mp3')
66	            ->toMediaCollection('assets')
67	            ->update(['asset_folder_id' => $child->id]);
68	
69	        $previews = $this->pageWithActiveFolder($parent)->getSubfolderPreviews();
70	
71	        $this->assertSame([], $previews[$child->id]);
72	    }
73	
74	    public function test_preview_collage_is_capped_at_four_thumbnails(): void
75	    {
76	        $parent = $this->product->createAssetFolder('Documenti');
77	        $child = $this->product->createAssetFolder('Foto', $parent);
78	
79	        foreach (range(1, 5) as $i) {
80	            $this->addImage($child, "photo-{$i}.jpg");
81	        }
82	
83	        $previews = $this->pageWithActiveFolder($parent)->getSubfolderPreviews();
84	
85	        $this->assertCount(AssetManager::FOLDER_PREVIEW_LIMIT, $previews[$child->id]);
86	    }
87	
88	    public function test_file_count_includes_descendants_and_non_displayable_media(): void
89	    {
90	        $parent = $this->product->createAssetFolder('Documenti');
91	        $child = $this->product->createAssetFolder('2024', $parent);
92	        $grandchild = $this->product->createAssetFolder('Gennaio', $child);
93	        $empty = $this->product->createAssetFolder('Vuota', $parent);
94	
95	        $this->addImage($child, 'a.jpg');
96	        $this->addImage($grandchild, 'b.jpg');
97	
98	        // conta anche i media senza anteprima mostrabile
99	        $this->product
100	            ->addMediaFromString('not an image')
101	            ->usingFileName('track.mp3')
102	            ->toMediaCollection('assets')
103	            ->update(['asset_folder_id' => $grandchild->id]);
104	
105	        $counts = $this->pageWithActiveFolder($parent)->getSubfolderFileCounts();
106	
107	        $this->assertSame(3, $counts[$child->id]);
108	        $this->assertSame(0, $counts[$empty->id]);
109	    }
110	
111	    public function test_processing_media_in_subfolder_tree_extends_polling(): void
112	    {
113	        $parent = $this->product->createAssetFolder('Documenti');
114	        $child = $this->product->createAssetFolder('Foto', $parent);
115	
116	        $media = $this->addImage($child);
117	        $media->update(['processing_status' => AssetProcessingStatus::Processing->value]);
118	
119	        $this->assertTrue($this->pageWithActiveFolder($parent)->hasProcessingInSubfolders());
120	
121	        $media->update(['processing_status' => AssetProcessingStatus::Completed->value]);
122	
123	        $this->assertFalse($this->pageWithActiveFolder($parent)->hasProcessingInSubfolders());
124	    }
125	
126	    /**
127	     * Istanza della page con la folder attiva impostata, per chiamare i metodi
128	     * di preview come farebbe il blade.
129	     */
130	    private function pageWithActiveFolder(AssetFolder $folder): AssetManager
131	    {
132	        /** @var AssetManager $page */
133	        $page = Livewire::test(AssetManager::class, ['ownerType' => 'product', 'owner' => $this->product->getKey()])
134	            ->call('selectFolder', $folder->id)
135	            ->instance();
136	
137	        return $page;
138	    }
