141	    {
142	        $image = imagecreatetruecolor(40, 25);
143	        ob_start();
144	        imagejpeg($image);
145	        $bytes = (string) ob_get_clean();
146	
147	        $media = $this->product
148	            ->addMediaFromString($bytes)
