/**
 * Tab del pannello info: "Informazioni" (metadati curati/normalizzati) e
 * "Metadati completi" (`extracted_metadata` grezzo, un blocco per tipo). Il
 * secondo tab compare solo se ci sono metadati estratti.
 *
 * Prende l'id del media, non l'oggetto: lo schema di 'infoAsset' viene
 * costruito una sola volta al mount e resta in cache (Filament,
 * `mountedActionSchema`) per tutta la vita dell'action montata — non si
 * ricostruisce da solo dopo "sostituisci file" (mount nidificato che cambia
 * il media sotto). I VALORI delle entry sono quindi closure che rifanno il
 * fetch a ogni render (vedi assetInfoEntries/assetMetadataSections); la sola
 * cosa che resta congelata all'apertura del pannello è la PRESENZA del tab
 * "Metadati completi" (decisa qui, una volta) — se il replace cambia tipo di
 * file passando da "senza metadati" a "con metadati" o viceversa, il tab
 * segue lo stato di quando il pannello è stato aperto, non quello corrente.
 */
private function assetInfoTabs(int|string $mediaKey): Tabs
{
    // prima tab con informazioni"
    $tabs = [
        Tab::make(__('digital-hub::assets.info_tab_summary'))
            ->schema($this->assetInfoEntries($mediaKey)),
    ];

    // seconda tab con le sezioni degli altri gruppi di metadati
    $media = $this->findOwnedMedia($mediaKey);
    $sections = $media === null ? [] : $this->assetMetadataSections($mediaKey, $media);
    if ($sections !== []) {
        $tabs[] = Tab::make(__('digital-hub::assets.info_tab_full'))
            ->schema($sections);
    }

    return Tabs::make()->tabs($tabs);
}

/**
 * Sezioni collassabili con i metadati estratti grezzi (`extracted_metadata`),
 * un blocco per chiave presente (`common`/`exif`/`iptc`/`xmp`). I valori
 * annidati (sezioni EXIF, liste IPTC) sono appiattiti in dot-notation perché
 * il KeyValueEntry rende solo coppie chiave→scalare. Vuoto se non ci sono
 * metadati (media non ancora processato).
 *
 * `$media` (già risolto dal chiamante, per decidere quali blocchi esistono)
 * serve solo a stabilire QUALI sezioni costruire; il CONTENUTO di ciascuna
 * (`KeyValueEntry::state()`) è una closure che rilegge `$mediaKey` a ogni
 * render, così un reprocess successivo (nuovi metadati) si riflette senza
 * dover riaprire il pannello.
 *
 * @return list<Section>
 */
private function assetMetadataSections(int|string $mediaKey, Media $media): array
{
    $metadata = ExtractedMetadata::forMedia($media);

    $labels = [
        'common' => __('digital-hub::assets.meta_block_common'),
        'exif' => 'EXIF',
        'iptc' => 'IPTC',
        'xmp' => 'XMP',
    ];

    $sections = [];
    foreach ($labels as $key => $label) {
        $block = $metadata[$key] ?? null;
        if (! is_array($block)) {
            continue;
        }

        $flat = ExtractedMetadata::flatten($block);
        if ($flat === []) {
            continue;
        }

        $sections[] = Section::make($label)
            ->heading('')
            // ->collapsible()
            // ->collapsed($key !== 'common') // i generali aperti, i blocchi grezzi chiusi
            ->schema([
                Fieldset::make($label)
                    ->columnSpanFull()
                    ->columns(1)
                    ->contained(false)
                    ->schema([
                        KeyValueEntry::make("meta_{$key}")
                            ->hiddenLabel()
                            ->state(function () use ($mediaKey, $key): array {
                                $media = $this->findOwnedMedia($mediaKey);
                                $block = $media === null ? null : (ExtractedMetadata::forMedia($media)[$key] ?? null);

                                return is_array($block) ? ExtractedMetadata::flatten($block) : [];
                            })
                            ->keyLabel(__('digital-hub::assets.meta_key'))
                            ->valueLabel(__('digital-hub::assets.meta_value')),
                    ]),
            ]);
    }

    return $sections;
}

/**
 * Voci (sola lettura) del tab "Informazioni": metadati curati/normalizzati,
 * dalla fonte unica {@see AssetSummary} (condivisa con la gallery di share).
 * Ogni valore è una closure che rilegge il media da `$mediaKey` a ogni
 * render (vedi assetInfoTabs): il NUMERO di entry resta quello di quando il
 * pannello è stato aperto (es. se il replace introduce/rimuove la voce
 * "Risoluzione" cambiando tipo di file, non compare/scompare da sola).
 *
 * @return list<Entry>
 */
private function assetInfoEntries(int|string $mediaKey): array
{
    $media = $this->findOwnedMedia($mediaKey);
    if ($media === null) {
        return [];
    }

    $entries = [];
    foreach (AssetSummary::forMedia($media) as $i => $row) {
        $entries[] = TextEntry::make("info_{$i}")
            ->label($row['label'])
            ->state(function () use ($mediaKey, $i): string {
                $media = $this->findOwnedMedia($mediaKey);

                return $media === null ? '' : (AssetSummary::forMedia($media)[$i]['value'] ?? '');
            });
    }

    return $entries;
}

